#!/usr/bin/env python3
"""Write a meson native file for the official GStreamer MSVC development package.

The glib-mkenums and glib-genmarshal of the package are Python scripts whose
first line names the packager's interpreter, for example
#!C:\\projects\\repos\\cerbero.git\\1.28\\build\\build-tools\\bin\\python.exe,
so meson fails to run them. The native file runs them with the Python that
runs this script, and points meson at the pkg-config and the .pc files of the
package.

The .pc files compute their prefix from their own location, and pkg-config
escapes the spaces of that prefix, so the package must be installed in a path
without spaces, such as C:\\gstreamer\\1.0\\msvc_x86_64 (or be given by its
8.3 short path).

Usage: gstreamer-native-file.py GSTREAMER_ROOT OUTPUT
"""

import os
import sys


def meson_string(path):
    return "'" + path.replace('\\', '/').replace("'", "\\'") + "'"


def main():
    if len(sys.argv) != 3:
        sys.exit(__doc__.strip().splitlines()[-1])

    root = os.path.abspath(sys.argv[1])
    output = sys.argv[2]

    files = {name: os.path.join(root, *name.split('/')) for name in
             ('bin/pkg-config.exe', 'bin/glib-mkenums', 'bin/glib-genmarshal', 'lib/pkgconfig')}
    missing = [path for path in files.values() if not os.path.exists(path)]
    if missing:
        sys.exit('Not a GStreamer MSVC development package, missing: ' + ', '.join(missing))
    if ' ' in root:
        print('warning: {} contains spaces, which break the prefix of its .pc files'.format(root))

    python = meson_string(sys.executable)
    with open(output, 'w', encoding='utf-8', newline='\n') as f:
        f.write('# Generated by {} for {}\n'.format(os.path.basename(__file__), root))
        f.write('[binaries]\n')
        f.write('pkg-config = {}\n'.format(meson_string(files['bin/pkg-config.exe'])))
        f.write('glib-mkenums = [{}, {}]\n'.format(python, meson_string(files['bin/glib-mkenums'])))
        f.write('glib-genmarshal = [{}, {}]\n'.format(python, meson_string(files['bin/glib-genmarshal'])))
        f.write('\n[properties]\n')
        f.write('pkg_config_libdir = [{}]\n'.format(meson_string(files['lib/pkgconfig'])))

    print('Wrote ' + output)
    return 0


if __name__ == '__main__':
    sys.exit(main())
